import sizes from "./sizes.json";
import type { IllustrationName } from "./registry";

export type { IllustrationName };

/**
 * Hand-drawn illustration served as a static SVG file (generated by scripts/build-illustrations.tsx).
 * - `title` becomes the alt text; without it the image is decorative.
 * - `priority` for above-the-fold art: loads eagerly at high priority. Everything else lazy-loads.
 * Width/height attributes reserve space, so nothing shifts while it loads.
 */
export function Illustration({
  name,
  className,
  title,
  priority = false,
}: {
  name: IllustrationName;
  className?: string;
  title?: string;
  priority?: boolean;
}) {
  const [w, h] = (sizes as unknown as Record<string, [number, number]>)[name] ?? [200, 160];
  return (
    // eslint-disable-next-line @next/next/no-img-element -- static SVG; next/image adds nothing here
    <img
      src={`/illustrations/${name}.svg`}
      width={w}
      height={h}
      alt={title ?? ""}
      aria-hidden={title ? undefined : true}
      className={`object-contain ${className ?? ""}`}
      loading={priority ? "eager" : "lazy"}
      fetchPriority={priority ? "high" : undefined}
      decoding="async"
      draggable={false}
    />
  );
}
